{%- assign group = Workflow | Attribute:'WorkerGroup','Object' -%}
{%- assign list = '' -%}
{%- if group.Id > 0 -%}
    {% groupmember where:'GroupId == {{ group.Id }} && GroupMemberStatus == 1 && IsArchived == false' securityenabled:'false' %}
        {%- for gm in groupmemberItems -%}
            {%- assign list = list | Append:gm.Person.PrimaryAlias.Guid | Append:',' -%}
        {%- endfor -%}
    {% endgroupmember %}
{%- endif -%}
{{ list }}

