Properties.Value:
{%- comment -%}
  Volunteer group members scheduled RIGHT NOW, minus anyone already in the
  Worker List so nobody is told twice.

  securityenabled:'false' on every entity command. A webhook-launched
  workflow has no logged-in person and entity commands apply Rock's entity
  security, which returns nothing silently. 

  Attribute:'Schedules' returns the schedule NAMES - 'RawValue' is required.
  RSVP != 0 keeps Yes, Maybe AND Unknown
  REQUIRES Enabled Lava Commands: RockEntity
{%- endcomment -%}
{%- assign group = Workflow | Attribute:'VolunteerGroup','Object' -%}
{%- assign workerList = Workflow | Attribute:'WorkerList' -%}
{%- assign offset = Workflow | Attribute:'OffsetMinutes' | AsInteger -%}
{%- assign scheduleGuids = Workflow | Attribute:'Schedules','RawValue' -%}
{%- assign today = 'Now' | Date:'yyyy-MM-dd' -%}
{%- assign now = 'Now' | Date:'yyyy-MM-ddTHH:mm:ss' -%}
{%- assign tomorrow = today | DateAdd:1,'d' | Date:'yyyy-MM-dd' -%}

{%- assign live = '' -%}
{%- assign scheduleList = scheduleGuids | Split:',' -%}
{%- for entry in scheduleList -%}
    {%- assign scheduleGuid = entry | Trim -%}

    {%- if scheduleGuid != '' -%}
        {% schedule where:'Guid == "{{ scheduleGuid }}"' limit:'1' securityenabled:'false' %}
            {%- for s in scheduleItems -%}
                {%- assign startsAt = today | Append:'T' | Append:s.StartTimeOfDay -%}
                {%- assign back = 0 | Minus:offset -%}
                {%- assign opens = startsAt | DateAdd:back,'m' | Date:'yyyy-MM-ddTHH:mm:ss' -%}
                {%- assign closes = startsAt | DateAdd:s.DurationInMinutes,'m' | Date:'yyyy-MM-ddTHH:mm:ss' -%}
                {%- if now >= opens and now <= closes -%}
                    {%- assign live = live | Append:s.Id | Append:',' -%}
                {%- endif -%}
            {%- endfor -%}
        {% endschedule %}
    {%- endif -%}
{%- endfor -%}

{%- assign list = '' -%}
{%- if live != '' and group.Id > 0 -%}
    {% attendanceoccurrence where:'GroupId == {{ group.Id }} && OccurrenceDate >= "{{ today }}" && OccurrenceDate < "{{ tomorrow }}"' limit:'20' securityenabled:'false' %}
        {%- for o in attendanceoccurrenceItems -%}
            {%- assign token = o.ScheduleId | Append:',' -%}
            {%- if live contains token -%}
                {% attendance where:'OccurrenceId == {{ o.Id }} && ScheduledToAttend == true && RSVP != 0' limit:'100' securityenabled:'false' %}
                {%- for a in attendanceItems -%}
                    {%- assign aliasGuid = a.PersonAlias.Person.PrimaryAlias.Guid -%}
                    {%- unless workerList contains aliasGuid -%}
                        {%- unless list contains aliasGuid -%}
                            {%- assign list = list | Append:aliasGuid | Append:',' -%}
                        {%- endunless -%}
                    {%- endunless -%}
                {%- endfor -%}
                {% endattendance %}
            {%- endif -%}
        {%- endfor -%}
    {% endattendanceoccurrence %}
{%- endif -%}
{{ list }}

